def is_valid(s: str) -> bool:
    matching = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)  # Save the newest unmatched opener.
        else:
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()  # Close the most recently opened bracket.
    return not stack

solution.java:
import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c); // Save the newest unmatched opener.
            } else {
                char expected = c == ')' ? '(' : c == ']' ? '[' : '{';
                if (stack.isEmpty() || stack.peek() != expected) {
                    return false;
                }
                stack.pop(); // Close the most recent opener.
            }
        }
        return stack.isEmpty();
    }
}

solution.javascript:
function isValid(s) {
    const matching = { ')': '(', ']': '[', '}': '{' };
    const stack = [];
    for (const char of s) {
        if ('([{'.includes(char)) {
            stack.push(char); // Save the newest unmatched opener.
        } else {
            if (stack.length === 0 || stack[stack.length - 1] !== matching[char]) {
                return false;
            }
            stack.pop(); // Close the most recent opener.
        }
    }
    return stack.length === 0;
}
